import{_ as d}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as c,a as u,b as m,c as h,d as g,e as f,f as b,g as t,h as v,i as l,j as n,k as x,l as y,m as q,n as z,o,p as k,q as _,r as A,s as F,t as w,u as P,v as D,w as s,x as L,y as C,z as E,A as S,B,C as N,D as I,E as T,F as V,G,H as M,I as U,J as O,K as R}from"./chunks/M-S-DS6aa7.CdBISpqM.js";import{_ as j}from"./chunks/M-S-DS2l2.BdmWUi3X.js";import{_ as Y}from"./chunks/M-S-SW8c.OZF8VB_x.js";import{_ as p}from"./chunks/OFF.BrU7kQE-.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as $}from"./chunks/M-S-PS5b.B4zocwby.js";import{_ as H,o as W,c as J,a3 as K}from"./chunks/framework.g9mfNVRQ.js";const he=JSON.parse('{"title":"Affichage","description":"","frontmatter":{"source_hash":"d238ff7b1e","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/display.md","filePath":"fr/use/display.md"}'),Q={name:"fr/use/display.md"};function X(Z,r,ee,ie,ae,se){return W(),J("div",null,[...r[0]||(r[0]=[K('<div class="admonition xdrip"><p class="admonition-title"><img src="'+d+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> xDrip+ Affichage</p></div><p>Ce menu vous permet de personnaliser de nombreux aspects visuels de xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">xDrip+ Affichage</p><p> Afficher les personnalisations</p></div><p><em>Remarque : consultez les fonctions des <a href="#graph-settings">Paramètres de Graph</a> avant d&#39;utiliser les paramètres de couleur.</em></p><h3 id="color-settings" tabindex="-1">Paramètres de couleur <a class="header-anchor" href="#color-settings" aria-label="Permalink to &quot;Paramètres de couleur {#color-settings}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">xDrip+ Couleurs</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_palette_grey600_48dp.png" style="width:8%;"> Personnaliser les couleurs</p></div><p>Le graphique d&#39;exemple en haut montre l&#39;effet de vos modifications.</p><div class="admonition xdripitem"><p class="admonition-title">Exemple Graphique</p><p> <img src="'+c+'" style="zoom:75%;"></p></div><p>Lorsque vous modifiez une couleur, vous pouvez choisir</p><ol><li>la teinte et la saturation</li><li>la luminosité ou l&#39;obscurité</li><li>la transparence.</li></ol><p>Le résultat s&#39;affiche à côté de la couleur d&#39;origine.</p><p>Vous pouvez rétablir la couleur par défaut ou l&#39;enregistrer.</p><img src="'+u+'" style="zoom:75%;"><h5 id="glucose-values-and-lines" tabindex="-1">Valeurs et lignes de glycémie <a class="header-anchor" href="#glucose-values-and-lines" aria-label="Permalink to &quot;Valeurs et lignes de glycémie {#glucose-values-and-lines}&quot;">​</a></h5><p>Vous pouvez personnaliser la courbe principale de glycémie. Les limites haute et basse sont définies dans les <a href="./settings.html#glucose-units">paramètres d&#39;unités de glycémie.</a></p><p>Les couleurs des valeurs hautes, dans la cible et basses modifient le graphique et les lignes de limite sur l&#39;écran principal, ainsi que sur les graphiques de la notification et du widget.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>VALEURS ET LIGNES DE GLYCÉMIE</small></small></p><p>Valeurs Hyperglycémies<span style="float:right;width:40px;height:40px;background-color:#FFBB33;display:inline-block;"></span></p><p>Valeurs de glycémie dans la cible<span style="float:right;width:40px;height:40px;background-color:#33B5E6;display:inline-block;"></span></p><p>Valeurs Hypoglycémies<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p><p>Mauvaises valeurs glycémiques<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Valeurs filtrées<span style="float:right;width:40px;height:40px;background-color:#A0A0A0;display:inline-block;"></span></p></div><img src="'+m+'" style="zoom:75%;"><p>Les valeurs incorrectes et filtrées sont visibles avec les capteurs qui fournissent des données brutes.</p><img src="'+h+'" style="zoom:75%;"><h5 id="colors-of-bg-readings-and-trend-arrows" tabindex="-1">Couleurs des valeurs de glycémie et des flèches de tendance <a class="header-anchor" href="#colors-of-bg-readings-and-trend-arrows" aria-label="Permalink to &quot;Couleurs des valeurs de glycémie et des flèches de tendance {#colors-of-bg-readings-and-trend-arrows}&quot;">​</a></h5><p>Vous pouvez aussi personnaliser la couleur de la glycémie actuelle et de la flèche de tendance en fonction des limites de la plage.</p><img src="'+g+'" style="zoom:75%;"><div class="admonition xdrip"><p class="admonition-title"><small><small>COULEURS DE VALEUR DE GLYCÉMIE ET DE FLÈCHE DE TENDANCE</small></small></p><p>Valeurs Hyperglycémies<span style="float:right;width:40px;height:40px;background-color:#FFBB33;display:inline-block;"></span></p><p>Valeurs de glycémie dans la cible<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Valeurs Hypoglycémies<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p><p>Prévision hypo (critique)<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p></div><p>Prévision hypo (critique) est la couleur du message de prévision d&#39;hypoglycémie sur l&#39;écran principal lorsque l&#39;hypoglycémie est proche.</p><h5 id="treatments-and-predictions-curves" tabindex="-1">Courbes de traitements et de prédictions <a class="header-anchor" href="#treatments-and-predictions-curves" aria-label="Permalink to &quot;Courbes de traitements et de prédictions {#treatments-and-predictions-curves}&quot;">​</a></h5><ol><li>Insuline active (courbe principale des <a href="./mainUI.html#units-of-insulin">traitements</a>)</li><li>Activité de l&#39;insuline (petite ligne pointillée)</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>TRAITEMENTS / COURBES DE PRÉVISION</small></small></p><p>Couleur de Traitement<span style="float:right;width:40px;height:40px;background-color:#77AA00;display:inline-block;"></span></p><p>Activité de l&#39;insuline<span style="float:right;width:40px;height:40px;background-color:#334400;display:inline-block;"></span></p></div><img src="'+f+'" style="zoom:75%;"><ol><li><a href="./predictions.html">Prédiction</a> de glycémie (courbe de prédiction principale)</li><li><a href="./mainUI.html#grams-of-carbs">Glucides</a> actifs (petite ligne pointillée)</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>TRAITEMENTS / COURBES DE PRÉVISION</small></small></p><p>Prédiction de Glycémie<span style="float:right;width:40px;height:40px;background-color:#AA66CC;display:inline-block;"></span></p><p>Prédictions de Glucides actifs<span style="float:right;width:40px;height:40px;background-color:#7700AA;display:inline-block;"></span></p></div><img src="'+b+'" style="zoom:75%;"><h5 id="average-and-target-lines" tabindex="-1">Lignes de moyenne et de cible <a class="header-anchor" href="#average-and-target-lines" aria-label="Permalink to &quot;Lignes de moyenne et de cible {#average-and-target-lines}&quot;">​</a></h5><ol><li>Ligne de moyenne sur 8 heures</li><li>Ligne de moyenne sur 24 heures</li><li>Ligne cible</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>LIGNES MOYENNE ET CIBLE</small></small></p><p>Ligne Moyenne de 8 heures<span style="float:right;width:40px;height:40px;background-color:#558800;display:inline-block;"></span></p><p>Ligne Moyenne 24 heures<span style="float:right;width:40px;height:40px;background-color:#C56F9D;display:inline-block;"></span></p><p>Ligne cible de la Glycémie<span style="float:right;width:40px;height:40px;background-color:#A4A409;display:inline-block;"></span></p></div><img src="'+t+'" style="zoom:75%;"><h5 id="annotations-and-dots" tabindex="-1">Annotations et points <a class="header-anchor" href="#annotations-and-dots" aria-label="Permalink to &quot;Annotations et points {#annotations-and-dots}&quot;">​</a></h5><p><a href="./mainUI.html#treatments">Tests sanguins (y compris les étalonnages) et traitements.</a></p><div class="admonition xdrip"><p class="admonition-title"><small><small>ANNOTATIONS ET DOTS</small></small></p><p>Arrière-plan du Test Sanguin<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Premier plan pour Test Sanguin<span style="float:right;width:40px;height:40px;background-color:#FF4444;display:inline-block;"></span></p><p>Arrière-plan de Traitement<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Premier plan de Traitement<span style="float:right;width:40px;height:40px;background-color:#77AA00;display:inline-block;"></span></p></div><h5 id="" tabindex="-1">{#} <a class="header-anchor" href="#" aria-label="Permalink to &quot;{#}&quot;">​</a></h5><img src="'+v+'" style="zoom:75%;"><h5 id="backgrounds" tabindex="-1">Arrière-plans <a class="header-anchor" href="#backgrounds" aria-label="Permalink to &quot;Arrière-plans {#backgrounds}&quot;">​</a></h5><p>Arrière-plans des graphiques, graphique principal</p><div class="admonition xdrip"><p class="admonition-title"><small><small>ARRIÈRE-PLANS</small></small></p><p>Arrière-plan du Graphique Principal <span style="float:right;width:40px;height:40px;background-color:#212121;border:1px solid #FFFFFF;display:inline-block;"></span></p><p>Arrière-plan du Graphique de Notification <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#FFFFFF;background-image:linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888), linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Arrière-plan du Widget Graphique <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#4C4C4C;background-image:linear-gradient(45deg, #333 25%, transparent 25%, transparent 75%, #333 75%, #333), linear-gradient(45deg, #333 25%, transparent 25%, transparent 75%, #333 75%, #333);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><p>Exemple : arrière-plan du graphique de notification</p><img src="'+l+'" style="zoom:75%;"><h5 id="plugins-and-features" tabindex="-1">Plugins et fonctionnalités <a class="header-anchor" href="#plugins-and-features" aria-label="Permalink to &quot;Plugins et fonctionnalités {#plugins-and-features}&quot;">​</a></h5><p>Si vous utilisez un <a href="./../calibrate/advancedcal.html#plugins">plugin</a>, vous pouvez aussi afficher la glycémie du plugin sous forme de graphique secondaire.<br> Tracés du Plugin sur le graphique doit être activé.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>PLUGINS ET FONCTIONNALITÉS</small></small></p><p>Valeur de glycémie du plugin secondaire <span style="float:right;width:40px;height:40px;background-color:#292A2B;border:1px solid #FFFFFF;display:inline-block;"></span></p></div><img src="'+j+'" style="zoom:75%;"><p>Si vous avez des données de pas et de fréquence cardiaque provenant d&#39;un <a href="./../smartwatch/smartwatch.html#smartwatch-sensors">appareil connecté</a>, vous pouvez personnaliser les couleurs du graphique.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>PLUGINS ET FONCTIONNALITÉS</small></small></p><p>Compteur de pas 1ère couleur <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#CBE5DF;background-image:linear-gradient(45deg, #6B857F 25%, transparent 25%, transparent 75%, #6B857F 75%, #6B857F), linear-gradient(45deg, #6B857F 25%, transparent 25%, transparent 75%, #6B857F 75%, #6B857F);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Compteur de pas 2ème couleur <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#DEF1F0;background-image:linear-gradient(45deg, #7D908F 25%, transparent 25%, transparent 75%, #7D908F 75%, #7D908F), linear-gradient(45deg, #7D908F 25%, transparent 25%, transparent 75%, #7D908F 75%, #7D908F);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Capteur de fréquence cardiaque <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#DADCF9;background-image:linear-gradient(45deg, #707290 25%, transparent 25%, transparent 75%, #707290 75%, #707290), linear-gradient(45deg, #707290 25%, transparent 25%, transparent 75%, #707290 75%, #707290);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><p>Dans l&#39;exemple ci-dessous : 1. fréquence cardiaque et 2. compteur de pas.</p><img src="'+Y+'" style="zoom:75%;"><h5 id="basal-and-smb" tabindex="-1">Basale et SMB <a class="header-anchor" href="#basal-and-smb" aria-label="Permalink to &quot;Basale et SMB {#basal-and-smb}&quot;">​</a></h5><p>Si vous parvenez à afficher la basale (<a href="#basal-information">depuis AAPS</a> ou par <a href="./predictions.html#basal-profile-editor">configuration manuelle</a>), vous pouvez aussi en personnaliser la couleur.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>COULEURS INSULINE</small></small></p><p>Basal TBR <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#558AE4;background-image:linear-gradient(45deg, #3F74CE 25%, transparent 25%, transparent 75%, #3F74CE 75%, #3F74CE), linear-gradient(45deg, #3F74CE 25%, transparent 25%, transparent 75%, #3F74CE 75%, #3F74CE);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Icône SMB <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#E4DF63;background-image:linear-gradient(45deg, #CEC94D 25%, transparent 25%, transparent 75%, #CEC94D 75%, #CEC94D), linear-gradient(45deg, #CEC94D 25%, transparent 25%, transparent 75%, #CEC94D 75%, #CEC94D);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Ligne SMB <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#7494D4;background-image:linear-gradient(45deg, #5F7FC0 25%, transparent 25%, transparent 75%, #5F7FC0 75%, #5F7FC0), linear-gradient(45deg, #5F7FC0 25%, transparent 25%, transparent 75%, #5F7FC0 75%, #5F7FC0);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><img src="'+n+'" style="zoom:75%;"><p>Les <a href="#smb">SMB</a> sont des icônes qui allègent le graphique pour les traitements par micro-bolus.</p><img src="'+x+'" style="zoom:75%;"><h5 id="flair-colors" tabindex="-1">Couleurs Flair <a class="header-anchor" href="#flair-colors" aria-label="Permalink to &quot;Couleurs Flair {#flair-colors}&quot;">​</a></h5><p>Si vous voulez mettre de la couleur sur les barres du haut et du bas de votre écran Android, activez les couleurs Flair.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>COULEURS ÉLÉGANTES</small></small></p><p>Barre de Titre/Navigation personnalisée <span style="float:right;"><img src="'+p+'" style="zoom:75%;"></span></p><p>Barre de titre supérieure <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#FFFFFF;background-image:linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888), linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Barre de navigation inférieure <span style="float:right;width:40px;height:40px;background-color:#000000;border:1px solid #FFFFFF;display:inline-block;"></span></p></div><p>Barre de titre supérieure :</p><img src="'+y+'" style="zoom:75%;"><p>Barre de navigation inférieure :</p><img src="'+q+'" style="zoom:75%;"><h3 id="font-settings" tabindex="-1">Paramètres de police <a class="header-anchor" href="#font-settings" aria-label="Permalink to &quot;Paramètres de police {#font-settings}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Paramètres de police</p><p> Personnaliser les polices</p></div><div class="admonition xdripitem"><p class="admonition-title">Agrandir les polices sur des écrans plus grands<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Agrandir automatiquement la taille de la police sur les grands écrans, comme les tablettes</p></div><h3 id="language" tabindex="-1">Langue <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Langue {#language}&quot;">​</a></h3><p>Par défaut, xDrip utilise la langue de votre téléphone. Vous pouvez choisir une autre langue pour xDrip et l&#39;imposer à la place de la langue du téléphone.</p><p>Pour cela :</p><p>Sélectionnez la langue dans Choisir une langue spécifique.</p><div class="admonition xdripitem"><p class="admonition-title">Choisir une langue spécifique</p></div><img src="'+z+'" style="zoom:75%;"><p>Activez l&#39;interrupteur Forcer le texte anglais.</p><div class="admonition xdripitem"><p class="admonition-title">Forcer le texte anglais<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><h3 id="smooth-sensor-noise" tabindex="-1">Bruit du capteur lissé <a class="header-anchor" href="#smooth-sensor-noise" aria-label="Permalink to &quot;Bruit du capteur lissé {#smooth-sensor-noise}&quot;">​</a></h3><p>Le lissage affiche la courbe lissée (il ne modifie pas les valeurs) ; utile pour les mesures bruitées.<br> Vous pouvez aussi essayer le <a href="#graph-smoothing">Lissage du graphique</a> pour nettoyer votre graphique.</p><div class="admonition xdripitem"><p class="admonition-title">⚠ Bruit du capteur lissé<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Essayez de pallier aux valeurs incorrectes</p></div><img src="'+o+'" style="zoom:75%;"><h3 id="show-interface-hints" tabindex="-1">Afficher les astuces de l&#39;interface <a class="header-anchor" href="#show-interface-hints" aria-label="Permalink to &quot;Afficher les astuces de l&#39;interface {#show-interface-hints}&quot;">​</a></h3><p>Après la première installation de xDrip, des astuces s&#39;affichent lors de la première ouverture de certaines fonctions ; vous pouvez désactiver ce comportement ou le réinitialiser.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher les astuces de l&#39;interface<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Afficher les astuces / conseils décrivant les fonctions des boutons etc. Décochez et revérifier pour réinitialiser au début</p></div><img src="'+k+'" style="zoom:75%;"><h3 id="graph-settings" tabindex="-1">Paramètres de Graph <a class="header-anchor" href="#graph-settings" aria-label="Permalink to &quot;Paramètres de Graph {#graph-settings}&quot;">​</a></h3><p>Vous pouvez personnaliser la plupart des éléments affichés sur le graphique principal.</p><div class="admonition xdripitem"><p class="admonition-title">Paramètres de Graph</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:8%;"> Ajuster les éléments du graphique</p></div><h5 id="graph-smoothing" tabindex="-1">Lissage du graphique <a class="header-anchor" href="#graph-smoothing" aria-label="Permalink to &quot;Lissage du graphique {#graph-smoothing}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Lissage du graphique</p></div><p>Le lissage du graphique applique un filtre de lissage au graphique pour le rendre plus facile à suivre (moins de bruit).</p><p>Il s&#39;agit uniquement d&#39;un effet visuel, sans impact sur les valeurs.</p><div class="admonition xdripitem"><p class="admonition-title">Activer <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Simplifier les graphiques en lissant les irrégularités des lectures précédentes. La lecture actuelle, les alertes et la valeur de diffusion ne sont pas affectées par ce paramètre.</p></div><img src="'+_+'" style="zoom:76%;"><img src="'+A+'" style="zoom:76%;"><div class="admonition xdripitem"><p class="admonition-title">Afficher non-lissées <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Afficher les données non lissées même si le lissage du graphique est activé. Si le plugin d&#39;étalonnage est utilisé, les données non lissées (au lieu des données du plugin) seront affichées.</p></div><h5 id="rewrite-history" tabindex="-1">Réécriture de l&#39;historique <a class="header-anchor" href="#rewrite-history" aria-label="Permalink to &quot;Réécriture de l&#39;historique {#rewrite-history}&quot;">​</a></h5><p>La réécriture de l&#39;historique adoucit les transitions après l&#39;ajout d&#39;un nouvel étalonnage, pour réduire l&#39;effet d&#39;escalier.<br> Assurez-vous qu&#39;elle est aussi activée sur les abonnés, pour éviter un affichage différent des glycémies passées.</p><div class="admonition xdripitem"><p class="admonition-title">Réécriture de l&#39;historique <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Après le calibrage, ajustez le graphique brut récent pour lisser à la nouvelle calibration</p></div><img src="'+F+'" style="zoom:75%;"><h5 id="widget-range-lines" tabindex="-1">Lignes de plage du widget <a class="header-anchor" href="#widget-range-lines" aria-label="Permalink to &quot;Lignes de plage du widget {#widget-range-lines}&quot;">​</a></h5><p>Vous pouvez choisir d&#39;afficher les lignes de limite haute et basse sur le widget.</p><div class="admonition xdripitem"><p class="admonition-title">Lignes de plage dans le widget <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Affiche une limite haute et basse sur le widget.</p></div><img src="'+w+'" style="zoom:75%;"><h5 id="main-graph-lines" tabindex="-1">Lignes du graphique principal <a class="header-anchor" href="#main-graph-lines" aria-label="Permalink to &quot;Lignes du graphique principal {#main-graph-lines}&quot;">​</a></h5><p>Vous pouvez désactiver les lignes verticales de temps sur le graphique principal.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher la grille de lignes de temps <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Grille de lignes de temps visible</p></div><img src="'+P+'" style="zoom:75%;"><p>Vous pouvez désactiver les lignes horizontales de glycémie sur le graphique principal.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher la grille des lignes de glycémie <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Grille de ligne de glycémie visible</p></div><img src="'+D+'" style="zoom:75%;"><h5 id="filtered-data" tabindex="-1">Données filtrées <a class="header-anchor" href="#filtered-data" aria-label="Permalink to &quot;Données filtrées {#filtered-data}&quot;">​</a></h5><p>La courbe filtrée ou lissée ajoute une autre courbe au graphique et peut, en option, créer les données manquantes.</p><div class="admonition xdripitem"><p class="admonition-title">Affichage graphique filtrée <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Utile pour le bruit et les lectures manquées</p></div><div class="admonition xdripitem"><p class="admonition-title">Créer les filtrées manquantes <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Rendre les données filtrées si nécessaire</p></div><img src="'+o+'" style="zoom:75%;"><p>Pour certaines sources de données (comme l&#39;application LL modifiée), cela affiche les données brutes non filtrées, puisque la glycémie affichée par xDrip est déjà filtrée.</p><img src="'+s+'" style="zoom:75%;"><h5 id="raw-data" tabindex="-1">Données brutes <a class="header-anchor" href="#raw-data" aria-label="Permalink to &quot;Données brutes {#raw-data}&quot;">​</a></h5><p>Données brutes que xDrip peut afficher si elles sont disponibles.</p><div class="admonition xdripitem"><p class="admonition-title">Affichage tracé de données brutes <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Les G4, G5 et G6 à batterie remplacée fournissent des données brutes.</p><img src="'+L+'" style="zoom:75%;"><p>Aujourd&#39;hui, les données brutes sont surtout visibles pour les capteurs Libre, mais pas avec cette option.<br> Pour les données brutes des capteurs Libre, utilisez <a href="./lesscommon.html#advanced-settings-for-libre-2">Paramètres avancés pour Libre 2</a>.</p><h5 id="basal-information" tabindex="-1">Informations de basale <a class="header-anchor" href="#basal-information" aria-label="Permalink to &quot;Informations de basale {#basal-information}&quot;">​</a></h5><p>Si des informations de basale sont disponibles depuis une source externe (<a href="https://androidaps.readthedocs.io/en/latest/index.html" target="_blank" rel="noreferrer">AAPS NSClient</a>), xDrip peut les afficher.</p><p>Dans AAPS/NSClient :</p><ul><li><p>Config builder</p></li><li><p>Synchronization - xDrip settings</p></li><li><p>Activez Send status line to xDrip</p></li></ul><img src="'+C+'" style="zoom:75%;"><p>Dans xDrip :</p><ul><li>Paramètres - Paramètres moins courants - activez Ligne d&#39;état supplémentaire - activez <a href="./lesscommon.html#extra-status-line">Statut externe</a></li><li>Paramètres - Paramètres inter applications - activez <a href="./interapp.html#receiving-from-nsclient">Accepter les traitements</a></li><li>Activez Afficher le Basal</li></ul><div class="admonition xdripitem"><p class="admonition-title">Afficher le Basal <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><img src="'+n+'" style="zoom:75%;"><p>Les informations de basale seront aussi envoyées à <a href="./cloud.html#tidepool">Tidepool</a>.</p><h5 id="target-and-average-lines" tabindex="-1">Lignes de cible et de moyenne <a class="header-anchor" href="#target-and-average-lines" aria-label="Permalink to &quot;Lignes de cible et de moyenne {#target-and-average-lines}&quot;">​</a></h5><p>Vous pouvez afficher différentes lignes de référence sur le graphique :</p><div class="admonition xdripitem"><p class="admonition-title">Afficher la ligne cible <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Afficher le graphique moyenne récente <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Afficher le graphique moyenne totale <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><ol><li>Ligne de moyenne sur 8 heures (récente)</li><li>Ligne de moyenne sur 24 heures (totale)</li><li>Ligne <a href="./predictions.html#low-level-prediction">cible</a></li></ol><img src="'+t+'" style="zoom:75%;"><h5 id="libre-trend" tabindex="-1">Tendance Libre <a class="header-anchor" href="#libre-trend" aria-label="Permalink to &quot;Tendance Libre {#libre-trend}&quot;">​</a></h5><p>La <a href="./3dotsmenu.html#libre-trend">tendance Libre</a> active un petit graphique accessible depuis le menu à trois points de l&#39;écran principal.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher la tendance du Freestyle Libre <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><h5 id="g6-predictions" tabindex="-1">Prédictions du G6 <a class="header-anchor" href="#g6-predictions" aria-label="Permalink to &quot;Prédictions du G6 {#g6-predictions}&quot;">​</a></h5><p>La Prédiction Dexcom est une fonction intégrée à l&#39;émetteur Dexcom G6, affichée sous forme de petits points gris.</p><div class="admonition xdripitem"><p class="admonition-title">Prédiction Dexcom <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher les points de glycémie prédictifs Dexcom</p></div><img src="'+E+'" style="zoom:75%;"><h5 id="smb" tabindex="-1">SMB <a class="header-anchor" href="#smb" aria-label="Permalink to &quot;SMB {#smb}&quot;">​</a></h5><p>Les SMB sont des icônes qui allègent le graphique pour les traitements par micro-bolus. Un appui sur un SMB affiche la quantité d&#39;insuline dans la ligne d&#39;information.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher les icônes micro bolus <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><img src="'+S+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Medtrum Secondaire <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Affiche les valeurs du capteur secondaire Medtrum A6.</p><h5 id="trend-momentum" tabindex="-1">Momentum de tendance <a class="header-anchor" href="#trend-momentum" aria-label="Permalink to &quot;Momentum de tendance {#trend-momentum}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Afficher la courbe de travail Momentum <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>Affiche une ligne pointillée rouge (1) qui prolonge la tendance actuelle de la glycémie (momentum) pour anticiper les hypos et hypers.<br> Elle est totalement indépendante des <a href="./predictions.html#use-trend-momentum">prédictions</a> (2) et ne tient pas compte des modèles de glucides ou d&#39;insuline.</p><img src="'+$+'" style="zoom:75%;"><h5 id="noise-workings" tabindex="-1">Fonctionnement du bruit <a class="header-anchor" href="#noise-workings" aria-label="Permalink to &quot;Fonctionnement du bruit {#noise-workings}&quot;">​</a></h5><p>Informations visuelles supplémentaires sur le calcul du bruit : une ligne jaune de cinq points à droite de la courbe.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher le fonctionnement de bruit <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><img src="'+s+'" style="zoom:75%;"><h5 id="backfilled-data" tabindex="-1">Données récupérées <a class="header-anchor" href="#backfilled-data" aria-label="Permalink to &quot;Données récupérées {#backfilled-data}&quot;">​</a></h5><p>Les données récupérées a posteriori (backfill) peuvent être signalées par un point bleu vide.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher les données récupérées <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><img src="'+B+'" style="zoom:75%;"><h5 id="widget-graph" tabindex="-1">Graphique du widget <a class="header-anchor" href="#widget-graph" aria-label="Permalink to &quot;Graphique du widget {#widget-graph}&quot;">​</a></h5><p>Vous pouvez masquer le graphique du <a href="./mainUI.html#widget">widget</a> pour ne garder que la valeur.</p><div class="admonition xdripitem"><p class="admonition-title">Masquer le graphe du widget <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><img src="'+N+'" style="zoom:75%;"><p>Ces deux options sont réservées aux développeurs.</p><div class="admonition xdripitem"><p class="admonition-title">Illustrer les données distantes <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><h5 id="y-axis" tabindex="-1">Axe Y <a class="header-anchor" href="#y-axis" aria-label="Permalink to &quot;Axe Y {#y-axis}&quot;">​</a></h5><p>L&#39;axe vertical de l&#39;écran principal a par défaut un minimum de 40 mg/dl (2,22 mmol/l) et un maximum de 250 mg/dl (13,9 mmol/l).</p><p>Vous pouvez fixer librement les valeurs basse et haute de l&#39;axe Y.</p><div class="admonition xdripitem"><p class="admonition-title">Personnaliser la plage de l&#39;axe y</p></div><p>Par défaut, lorsque des valeurs sortent de cette plage, le graphique l&#39;élargit temporairement pour les rendre visibles, puis revient à vos valeurs fixes une fois ces valeurs sorties de l&#39;écran.</p><p>Si vous préférez garder une plage fixe pour l&#39;axe Y et faire défiler le graphique verticalement au lieu de l&#39;élargir, activez Auto-pan Y-axis.</p><div class="admonition xdripitem"><p class="admonition-title">Auto-pan Y-axis <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> <strong>Enable:</strong> Pan the graph with a fixed Y-axis range (minimum–maximum) to show out-of-range readings.<br>  <strong>Disable:</strong> Expand the Y-axis range to include out-of-range readings.</p></div><h3 id="glucose-number-from-filtered" tabindex="-1">Glycémie depuis les données filtrées <a class="header-anchor" href="#glucose-number-from-filtered" aria-label="Permalink to &quot;Glycémie depuis les données filtrées {#glucose-number-from-filtered}&quot;">​</a></h3><p>Le filtrage peut retarder les valeurs et n&#39;est pas recommandé.<br> Le filtrage est imposé par le matériel pour la <a href="./../install/libre2patch.html">source de données Application Libre 2 modifiée</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Numéro Glucose de la liste filtrée <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><img src="'+s+'" style="zoom:75%;"><h3 id="bolus-wizard-preview" tabindex="-1">Aperçu de l&#39;assistant de bolus <a class="header-anchor" href="#bolus-wizard-preview" aria-label="Permalink to &quot;Aperçu de l&#39;assistant de bolus {#bolus-wizard-preview}&quot;">​</a></h3><p>Le BWP (Bolus Wizard Preview) affiche l&#39;insuline active (IoB) et propose des corrections en fonction des paramètres de <a href="./predictions.html">prédiction</a> saisis dans xDrip.<br> Il s&#39;agit d&#39;une indication. Assurez-vous d&#39;avoir compris le CLUF avant de l&#39;utiliser.<br> Ne suivez jamais les suggestions lorsque la glycémie évolue rapidement.</p><p>L&#39;aperçu de l&#39;assistant de bolus ne s&#39;affiche que s&#39;il y a des glucides ou de l&#39;insuline.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher l&#39;aperçu de l&#39;assistant de bolus <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher les calculs de l&#39;insuline/glucides</p></div><img src="'+I+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Toujours afficher l’aperçu d’assistant de Bolus <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher les calculs de l&#39;insuline/glucides en permanence</p></div><p>Si vous forcez l&#39;affichage permanent du BWP, il proposera toujours une correction (insuline ou glucides).</p><img src="'+T+'" style="zoom:75%;"><h3 id="high-priority-notifications" tabindex="-1">Notifications en priorité élevée <a class="header-anchor" href="#high-priority-notifications" aria-label="Permalink to &quot;Notifications en priorité élevée {#high-priority-notifications}&quot;">​</a></h3><p>Cette option place le <a href="./misc.html#run-collector-in-foreground">graphique et les notifications</a> de xDrip en haut de la liste ; la désactiver les fait descendre.</p><p>Vous pouvez désactiver Notifications en priorité élevée si vous préférez que xDrip soit plus bas dans la liste des notifications. Le <a href="./misc.html#run-collector-in-foreground">collecteur tourne toujours au premier plan</a> sur Android 8.0 et supérieur : Android ne mettra donc pas xDrip en veille.</p><div class="admonition xdripitem"><p class="admonition-title">Notifications en priorité élevée<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Afficher les notifications et les graphiques en haut (également utiles sur l&#39;écran de verrouillage)</p></div><img src="'+l+'" style="zoom:75%;"><h3 id="public-notifications" tabindex="-1">Notifications publiques <a class="header-anchor" href="#public-notifications" aria-label="Permalink to &quot;Notifications publiques {#public-notifications}&quot;">​</a></h3><p>Cette option rend les notifications visibles sur l&#39;écran verrouillé.</p><div class="admonition xdripitem"><p class="admonition-title">Notifications publiques <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><h3 id="enable-reminder-features" tabindex="-1">Activer les fonctionnalités de rappel <a class="header-anchor" href="#enable-reminder-features" aria-label="Permalink to &quot;Activer les fonctionnalités de rappel {#enable-reminder-features}&quot;">​</a></h3><p>Activée par défaut : vous trouverez les rappels dans le <a href="./3dotsmenu.html">menu à trois points</a> en haut à droite de l&#39;écran principal.</p><div class="admonition xdripitem"><p class="admonition-title">Activer les fonctionnalités de rappel <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Afficher les menus et fonctionnalités de Rappel</p></div><h3 id="always-on-display-settings" tabindex="-1">Paramètres Always On Display <a class="header-anchor" href="#always-on-display-settings" aria-label="Permalink to &quot;Paramètres Always On Display {#always-on-display-settings}&quot;">​</a></h3><p>xDrip peut utiliser l&#39;accessibilité Android pour afficher son widget sur l&#39;écran Always On Display, si votre téléphone le permet.</p><div class="admonition xdripitem"><p class="admonition-title">Activer l&#39;accessibilité xDrip</p><p> Si votre téléphone est compatible avec la fonction &quot;Always On Display&quot;, vous pouvez activer le widget xDrip en activant le service d&#39;accessibilité xDrip depuis les paramètres Android.</p></div><img src="'+V+'" style="zoom:75%;"><img src="'+G+'" style="zoom:75%;"><p>Sur Android 16 et supérieur, vous pouvez aussi afficher votre glycémie sous forme de puce de notification sur l&#39;écran de verrouillage / Always On Display, en utilisant la notification persistante au lieu de l&#39;accessibilité. Cela repose sur les <a href="./alarms.html#notification-channels">canaux de notification</a>, toujours actifs sur Android 8.0 et supérieur.</p><div class="admonition xdripitem"><p class="admonition-title">Use AOD chip style <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Display notification chip and lockscreen notification. Android 16+ only</p></div><h3 id="numbered-wall-on-locked-screen" tabindex="-1">Mur de chiffres sur l&#39;écran de verrouillage <a class="header-anchor" href="#numbered-wall-on-locked-screen" aria-label="Permalink to &quot;Mur de chiffres sur l&#39;écran de verrouillage {#numbered-wall-on-locked-screen}&quot;">​</a></h3><p>xDrip peut afficher votre glycémie sur l&#39;écran verrouillé du téléphone.</p><div class="admonition xdripitem"><p class="admonition-title">Mur de chiffres sur l&#39;écran de verrouillage</p></div><p>Ce menu vous permet de personnaliser le nombre affiché.</p><div class="admonition xdripitem"><p class="admonition-title">Configurer le mur de chiffres</p><p>Ajuster et prévisualiser la mise en page du mur</p></div><p>Vous verrez un aperçu en temps réel du résultat (123 ⇅)</p><ol><li>Modifier la taille de police</li><li>Modifier la position verticale (ou l&#39;écart vertical entre les chiffres)</li><li>Modifier la position horizontale (ou l&#39;écart horizontal entre les chiffres)</li><li>Modifier la couleur des chiffres</li><li>Sélectionner l&#39;image de fond</li><li>Le mur de chiffres lui-même</li></ol><img src="'+M+'" style="zoom:75%;"><p>Activez l&#39;affichage sur l&#39;écran verrouillé pour afficher le mur de chiffres.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher sur l&#39;écran de verrouillage<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Afficher sur l&#39;écran de verrouillage. Android 7 et plus seulement!</p></div><p>Par défaut, le mur de chiffres de l&#39;écran de verrouillage utilise les mêmes couleurs bas / dans la cible / haut que l&#39;écran principal. Vous pouvez le forcer à toujours utiliser une seule couleur fixe.</p><div class="admonition xdripitem"><p class="admonition-title">Force text color<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Enable: Always use the selected text color.<br>  Disable: Use main screen glucose colors (low / in-range / high).</p></div><div class="admonition xdrip"><p class="admonition-title">Mur de chiffres sur l&#39;écran de verrouillage</p><p>Couleur de texte sur le mur<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Couleur de l&#39;ombre sur le mur<span style="float:right;width:40px;height:40px;background-color:#000000;display:inline-block;"></span></p></div><p>Activez et désactivez la fonction sur une période définie de la journée. Par défaut, elle est active toute la journée.</p><div class="admonition xdripitem"><p class="admonition-title">Mettre en marche</p><p>Choisir le moment du début d&#39;affichage</p></div><div class="admonition xdripitem"><p class="admonition-title">Désactiver l&#39;heure</p><p>Choisir le moment d&#39;arrêter - définir à la même valeur que le démarrage pour toujours actif</p></div><h3 id="number-icon-in-notification-area" tabindex="-1">Icône Valeur dans la zone de notification <a class="header-anchor" href="#number-icon-in-notification-area" aria-label="Permalink to &quot;Icône Valeur dans la zone de notification {#number-icon-in-notification-area}&quot;">​</a></h3><p>xDrip peut afficher votre glycémie sous forme d&#39;icône dans la zone de notification en haut à gauche et dans le volet des notifications.</p><img src="'+U+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Icône Valeur dans la zone de notification</p></div><p><strong>Testez la fonction avant de l&#39;utiliser, car elle peut faire planter certains téléphones.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Lancer le test d&#39;icône Valeur</p><p> Les icônes de Valeurs plantent certains téléphones ! Appuyez pour exécuter le test avant d&#39;activer la fonctionnalité!</p></div><img src="'+O+'" style="zoom:75%;"><p>Votre téléphone vibrera plusieurs fois pendant le test et vous devriez voir l&#39;icône de glycémie 123 en haut à gauche.</p><img src="'+R+'" style="zoom:75%;"><p>Si cela ne fonctionne pas, n&#39;activez pas la fonction.</p><p><strong>Une fois le fonctionnement confirmé</strong>, vous pouvez l&#39;activer.</p><div class="admonition xdripitem"><p class="admonition-title">Icône de Valeur testé<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Lorsque vous aurez confirmé, votre appareil pourra afficher une icône de valeur</p></div><div class="admonition xdripitem"><p class="admonition-title">Afficher l&#39;icône Valeur en petit<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Affiche la valeur de glycémie actuelle comme icône pour la barre de notification et l&#39;écran de verrouillage</p></div><h3 id="show-xdrip-on-boot" tabindex="-1">Afficher xDrip au démarrage <a class="header-anchor" href="#show-xdrip-on-boot" aria-label="Permalink to &quot;Afficher xDrip au démarrage {#show-xdrip-on-boot}&quot;">​</a></h3><p>Cette option ouvre automatiquement xDrip au redémarrage de votre téléphone.</p><p>Il peut être utile de l&#39;activer si votre téléphone effectue des mises à jour et redémarrages automatiques (déconseillé) et que xDrip ne démarre pas automatiquement au redémarrage.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher xDrip au démarrage <span class="symbol"><img src="'+p+'" style="zoom:75%;"></span></p><p> Afficher l&#39;écran xDrip automatiquement après le démarrage de l&#39;appareil</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',245)])])}const ge=H(Q,[["render",X]]);export{he as __pageData,ge as default};
